const POLL: Duration = Duration::from_millis(20);

fn fixture(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(name)
}

fn fixture_bytes(name: &str) -> Vec<u8> {
    std::fs::read(fixture(name)).unwrap()
}

/// 16-bit PCM WAV, `channels` interleaved, a sine at `freq` Hz.
fn wav(rate: u32, channels: u16, secs: f32, freq: f32) -> Vec<u8> {
    let frames = (rate as f32 * secs) as u32;
    let data_len = frames * u32::from(channels) * 2;
    let mut out = Vec::new();
    out.extend_from_slice(b"RIFF");
    out.extend_from_slice(&(36 + data_len).to_le_bytes());
    out.extend_from_slice(b"WAVEfmt ");
    out.extend_from_slice(&16u32.to_le_bytes());
    out.extend_from_slice(&1u16.to_le_bytes());
    out.extend_from_slice(&channels.to_le_bytes());
    out.extend_from_slice(&rate.to_le_bytes());
    out.extend_from_slice(&(rate * u32::from(channels) * 2).to_le_bytes());
    out.extend_from_slice(&(channels * 2).to_le_bytes());
    out.extend_from_slice(&16u16.to_le_bytes());
    out.extend_from_slice(b"data");
    out.extend_from_slice(&data_len.to_le_bytes());
    for i in 0..frames {
        let v = (2.0 * std::f32::consts::PI * freq * i as f32 / rate as f32).sin() * 0.5;
        let s = (v * i16::MAX as f32) as i16;
        for _ in 0..channels {
            out.extend_from_slice(&s.to_le_bytes());
        }
    }
    out
}

// ------------------------------------------------------------------ formats

#[test]
fn media_formats_are_recognized_with_duration() {
    for (name, kind, media_type) in [
        ("lezione.mp3", DocumentKind::Audio, "audio/mpeg"),
        ("lezione.m4a", DocumentKind::Audio, "audio/mp4"),
        ("lezione.mp4", DocumentKind::Video, "video/mp4"),
    ] {
        let bytes = fixture_bytes(name);
        let f = detect_format(name, &bytes).unwrap();
        assert_eq!((f.kind, f.media_type), (kind, media_type), "{name}");
        let ms = f
            .duration_ms
            .unwrap_or_else(|| panic!("{name}: no duration"));
        assert!((9_000..10_000).contains(&ms), "{name}: {ms} ms");
        // Same result from the file (chunked uploads), without reading it whole.
        let from_file = detect_media_file(name, &fixture(name)).unwrap().unwrap();
        assert_eq!(from_file, f, "{name}");
    }
    let video = detect_format("lezione.mp4", &fixture_bytes("lezione.mp4")).unwrap();
    assert_eq!(video.image_size, Some((64, 48)));
    let audio = detect_format("lezione.m4a", &fixture_bytes("lezione.m4a")).unwrap();
    assert_eq!(audio.image_size, None);

    let w = wav(44_100, 2, 1.5, 440.0);
    let f = detect_format("tono.wav", &w).unwrap();
    assert_eq!((f.kind, f.media_type), (DocumentKind::Audio, "audio/wav"));
    assert_eq!(f.duration_ms, Some(1500));

    // A video without an audio track is still a video.
    let muto = detect_format("muto.mp4", &fixture_bytes("muto.mp4")).unwrap();
    assert_eq!(muto.kind, DocumentKind::Video);
    assert_eq!(muto.image_size, Some((32, 24)));

    // Non-media extensions are left to the 0.2 rules.
    assert!(detect_media_file("a.pdf", &fixture("lezione.mp3"))
        .unwrap()
        .is_none());
}

#[test]
fn media_mismatches_and_damage_are_unsupported() {
    let mp3 = fixture_bytes("lezione.mp3");
    let mp4 = fixture_bytes("lezione.mp4");
    let cases: Vec<(&str, Vec<u8>, &str)> = vec![
        ("finto.wav", mp3.clone(), "non è un audio WAV"),
        ("finto.mp3", mp4.clone(), "non è un audio MP3"),
        ("finto.mp4", mp3.clone(), "non è un video MP4"),
        ("finto.m4a", b"%PDF-1.4".to_vec(), "non è un audio M4A"),
        (
            "testo.mp3",
            b"solo testo, niente audio".to_vec(),
            "non è un audio MP3",
        ),
        // Right signature, broken container.
        (
            "rotto.mp4",
            {
                let mut b = mp4[..64].to_vec();
                b.extend(std::iter::repeat_n(0u8, 256));
                b
            },
            "danneggiato",
        ),
        (
            "muto.m4a",
            fixture_bytes("muto.mp4"),
            "non contiene una traccia audio",
        ),
    ];
    for (name, bytes, expected) in cases {
        match detect_format(name, &bytes) {
            Err(CoreError::Unsupported { message }) => {
                assert!(message.contains(expected), "{name}: {message}")
            }
            other => panic!("{name}: {other:?}"),
        }
    }
    // A text file starting like an ID3 tag is still text.
    assert_eq!(
        detect_format("nota.txt", b"ID3 e altre sigle")
            .unwrap()
            .kind,
        DocumentKind::Text
    );
    assert_eq!(
        kind_for_file_name("Lezione.MP4").unwrap(),
        DocumentKind::Video
    );
    assert!(matches!(
        kind_for_file_name("a.ogg"),
        Err(CoreError::Unsupported { .. })
    ));
}

// ------------------------------------------------------------------ decoding

#[test]
fn decoding_gives_16khz_mono_of_the_right_length() {
    let never = AtomicBool::new(false);
    for name in ["lezione.mp3", "lezione.m4a", "lezione.mp4"] {
        let file = std::fs::File::open(fixture(name)).unwrap();
        let ext = name.rsplit('.').next().unwrap();
        let mut last = 0.0f32;
        let audio = decode_to_whisper(Box::new(file), ext, &never, |p| last = p).unwrap();
        let ms = audio.duration_ms();
        assert!((9_000..10_000).contains(&ms), "{name}: {ms} ms");
        assert_eq!(last, 1.0);
        let peak = audio.samples.iter().fold(0.0f32, |m, s| m.max(s.abs()));
        assert!(peak > 0.05 && peak <= 1.0, "{name}: peak {peak}");
        // The first second is silence (see make_fixtures.sh).
        let lead = audio.samples[..12_000]
            .iter()
            .fold(0.0f32, |m, s| m.max(s.abs()));
        assert!(lead < 0.05, "{name}: lead {lead}");
    }
    // Stereo 44.1 kHz WAV: downmixed and resampled, pitch preserved.
    let w = wav(44_100, 2, 2.0, 440.0);
    let audio =
        decode_to_whisper(Box::new(std::io::Cursor::new(w)), "wav", &never, |_| {}).unwrap();
    assert_eq!(audio.samples.len(), 32_000);
    let crossings = audio.samples[1000..31_000]
        .windows(2)
        .filter(|p| p[0] <= 0.0 && p[1] > 0.0)
        .count();
    let freq = crossings as f32 * 16_000.0 / 30_000.0;
    assert!((freq - 440.0).abs() < 5.0, "{freq}");
}

#[test]
fn decoding_can_be_cancelled_and_rejects_videos_without_audio() {
    let cancel = AtomicBool::new(true);
    let file = std::fs::File::open(fixture("lezione.mp3")).unwrap();
    assert_eq!(
        decode_to_whisper(Box::new(file), "mp3", &cancel, |_| {}).unwrap_err(),
        DecodeError::Cancelled
    );
    let never = AtomicBool::new(false);
    let file = std::fs::File::open(fixture("muto.mp4")).unwrap();
    assert!(matches!(
        decode_to_whisper(Box::new(file), "mp4", &never, |_| {}),
        Err(DecodeError::Unsupported(_))
    ));
}

// ------------------------------------------------------------------ chunked upload

struct UploadEnv {
    env: Env,
    uploads: Uploads,
}

impl UploadEnv {
    fn new() -> Self {
        let env = Env::new();
        let uploads = Uploads::new(&env.originals());
        UploadEnv { env, uploads }
    }

    fn begin(&self, project: &str, name: &str, size: u64, document: Option<&str>) -> String {
        let input = BeginUpload {
            project_id: project.into(),
            folder_id: None,
            file_name: name.into(),
            size_bytes: size,
            last_modified: Some(1_700_000_000_000),
            document_id: document.map(str::to_owned),
        };
        self.env.store.check_upload_target(&input).unwrap();
        self.uploads.begin(input).unwrap().upload_id
    }

    /// Uploads `bytes` in blocks of `block` bytes and imports them.
    fn upload(
        &mut self,
        project: &str,
        name: &str,
        bytes: &[u8],
        block: usize,
        document: Option<&str>,
    ) -> ImportOutcome {
        let id = self.begin(project, name, bytes.len() as u64, document);
        let mut offset = 0u64;
        for chunk in bytes.chunks(block) {
            self.uploads.write_chunk(&id, offset, chunk).unwrap();
            offset += chunk.len() as u64;
        }
        let finished = self.uploads.finish(&id).unwrap();
        let file = finished.prepare().unwrap();
        self.env.store.import_upload(&finished, &file).unwrap()
    }

    fn temp_files(&self) -> usize {
        std::fs::read_dir(self.uploads.dir())
            .map(|d| d.count())
            .unwrap_or(0)
    }
}

fn imported(outcome: ImportOutcome) -> LibraryDocument {
    match outcome {
        ImportOutcome::Imported(d) => d,
        ImportOutcome::Duplicate(d) => panic!("unexpected duplicate {d:?}"),
    }
}

#[test]
fn chunked_upload_imports_media_and_follows_the_import_rules() {
    let mut u = UploadEnv::new();
    let p = u.env.project("Lezioni").id;
    let mp3 = fixture_bytes("lezione.mp3");
    let doc = imported(u.upload(&p, "lezione.mp3", &mp3, 5_000, None));
    let v = &doc.current;
    assert_eq!(v.kind, DocumentKind::Audio);
    assert_eq!(v.media_type, "audio/mpeg");
    assert_eq!(v.size_bytes, mp3.len() as u64);
    assert_eq!(v.sha256, sha256_hex(&mp3));
    assert_eq!(v.text_status, TextStatus::NotApplicable);
    assert!(v.duration_ms.is_some_and(|d| (9_000..10_000).contains(&d)));
    assert!(v.transcription.is_none());
    assert_eq!(std::fs::read(u.env.blob_path(&v.sha256)).unwrap(), mp3);
    assert_eq!(u.temp_files(), 0, "temp file moved into the archive");
    // No extraction job for recordings.
    assert!(u.env.store.list_jobs(&p).unwrap().is_empty());

    // Same bytes again: duplicate, temp file removed.
    match u.upload(&p, "copia.mp3", &mp3, 64 * 1024, None) {
        ImportOutcome::Duplicate(d) => assert_eq!(d.id, doc.id),
        other => panic!("{other:?}"),
    }
    assert_eq!(u.temp_files(), 0);

    // A new version of the same kind (audio → audio), via documentId.
    let m4a = fixture_bytes("lezione.m4a");
    let doc2 = imported(u.upload(&p, "lezione.m4a", &m4a, 10_000, Some(&doc.id)));
    assert_eq!(doc2.id, doc.id);
    assert_eq!(doc2.version_count, 2);
    assert_eq!(doc2.current.media_type, "audio/mp4");

    // A video: dimensions recorded.
    let video = imported(u.upload(
        &p,
        "lezione.mp4",
        &fixture_bytes("lezione.mp4"),
        7_777,
        None,
    ));
    assert_eq!(video.current.kind, DocumentKind::Video);
    assert_eq!(
        (video.current.image_width, video.current.image_height),
        (Some(64), Some(48))
    );

    // Non-media through chunks too: the 0.2 extraction still runs.
    let text = "Appunti caricati a blocchi sulla derivata.\n\nSeconda parte.".repeat(50);
    let notes = imported(u.upload(&p, "appunti.txt", text.as_bytes(), 1000, None));
    assert_eq!(notes.current.text_status, TextStatus::Pending);
    assert_eq!(u.env.run_jobs(), 1);
    assert_eq!(
        u.env
            .store
            .get_version(&notes.current.id)
            .unwrap()
            .text_status,
        TextStatus::Extracted
    );
    assert_eq!(u.temp_files(), 0);
}

#[test]
fn chunked_upload_checks_offsets_size_and_target() {
    let mut u = UploadEnv::new();
    let p = u.env.project("Lezioni").id;
    let mp3 = fixture_bytes("lezione.mp3");
    let id = u.begin(&p, "lezione.mp3", mp3.len() as u64, None);
    let validation = |r: Result<(), CoreError>| match r {
        Err(CoreError::Validation { message, .. }) => message,
        other => panic!("{other:?}"),
    };
    // Offsets must be consecutive.
    validation(u.uploads.write_chunk(&id, 10, &mp3[..100]));
    u.uploads.write_chunk(&id, 0, &mp3[..100]).unwrap();
    validation(u.uploads.write_chunk(&id, 0, &mp3[..100]));
    validation(u.uploads.write_chunk(&id, 200, &mp3[100..200]));
    validation(u.uploads.write_chunk(&id, 100, &[]));
    // Not past the declared size.
    let mut too_much = mp3[100..].to_vec();
    too_much.push(0);
    let m = validation(u.uploads.write_chunk(&id, 100, &too_much));
    assert!(m.contains("dimensione dichiarata"), "{m}");
    // Finishing early is refused, and the upload stays usable.
    assert!(matches!(
        u.uploads.finish(&id),
        Err(CoreError::Validation { .. })
    ));
    u.uploads.write_chunk(&id, 100, &mp3[100..]).unwrap();
    let finished = u.uploads.finish(&id).unwrap();
    assert_eq!(finished.sha256, sha256_hex(&mp3));
    // Finished uploads cannot receive more or finish twice.
    assert!(matches!(
        u.uploads.write_chunk(&id, 0, &mp3[..1]),
        Err(CoreError::NotFound { .. })
    ));
    assert!(matches!(
        u.uploads.finish(&id),
        Err(CoreError::NotFound { .. })
    ));
    drop(finished);
    assert_eq!(
        u.temp_files(),
        0,
        "dropping an unimported upload removes it"
    );

    // Block size limit.
    let big = vec![0u8; UPLOAD_CHUNK_BYTES as usize + 1];
    let id = u.begin(&p, "grande.wav", big.len() as u64, None);
    validation(u.uploads.write_chunk(&id, 0, &big));
    u.uploads.cancel(&id);

    // Size limits by kind, before anything is received.
    let begin = |name: &str, size: u64| {
        u.uploads.begin(BeginUpload {
            project_id: p.clone(),
            file_name: name.into(),
            size_bytes: size,
            ..BeginUpload::default()
        })
    };
    assert!(begin("lezione.mp4", 4 * 1024 * 1024 * 1024).is_ok());
    assert!(matches!(
        begin("lezione.mp4", 4 * 1024 * 1024 * 1024 + 1),
        Err(CoreError::TooLarge { .. })
    ));
    assert!(matches!(
        begin("dispense.pdf", 200 * 1024 * 1024 + 1),
        Err(CoreError::TooLarge { .. })
    ));
    assert!(matches!(
        begin("a.mp3", 0),
        Err(CoreError::Validation { .. })
    ));
    assert!(matches!(
        begin("a.exe", 10),
        Err(CoreError::Unsupported { .. })
    ));
    assert!(matches!(
        begin("../a.mp3", 10),
        Err(CoreError::Validation { .. })
    ));

    // Destination checks.
    let check = |store: &Store, input: BeginUpload| store.check_upload_target(&input);
    assert!(matches!(
        check(
            &u.env.store,
            BeginUpload {
                project_id: "missing".into(),
                file_name: "a.mp3".into(),
                size_bytes: 1,
                ..BeginUpload::default()
            }
        ),
        Err(CoreError::NotFound { .. })
    ));
    let pdf_doc = u
        .env
        .import(&p, "slide.pdf", &pdf(&[&text_page(&[b"Slide"])]));
    assert!(matches!(
        check(
            &u.env.store,
            BeginUpload {
                project_id: p.clone(),
                file_name: "a.mp3".into(),
                size_bytes: 1,
                document_id: Some(pdf_doc.id.clone()),
                ..BeginUpload::default()
            }
        ),
        Err(CoreError::Validation { field: "file", .. })
    ));
    let other = u.env.project("Altro").id;
    let folder = u
        .env
        .store
        .create_folder(localis_core::NewFolder {
            project_id: other,
            parent_id: None,
            name: "Cartella".into(),
        })
        .unwrap();
    assert!(matches!(
        check(
            &u.env.store,
            BeginUpload {
                project_id: p.clone(),
                folder_id: Some(folder.id),
                file_name: "a.mp3".into(),
                size_bytes: 1,
                ..BeginUpload::default()
            }
        ),
        Err(CoreError::Validation {
            field: "folderId",
            ..
        })
    ));

    // Content that does not match the extension is refused at finish; temp removed.
    let fake = b"questo non e' audio".to_vec();
    let id = u.begin(&p, "finto.mp3", fake.len() as u64, None);
    u.uploads.write_chunk(&id, 0, &fake).unwrap();
    let finished = u.uploads.finish(&id).unwrap();
    assert!(matches!(
        finished.prepare(),
        Err(CoreError::Unsupported { .. })
    ));
    drop(finished);
    let _ = u.env.store.list_documents(&p).unwrap();
    assert_eq!(
        u.temp_files(),
        1,
        "only the 4 GB upload begun above remains"
    );
}

#[test]
fn uploads_are_cancelled_and_swept() {
    let mut u = UploadEnv::new();
    let p = u.env.project("Lezioni").id;
    let a = u.begin(&p, "a.mp3", 1000, None);
    u.uploads.write_chunk(&a, 0, &[1; 10]).unwrap();
    assert_eq!(u.temp_files(), 1);
    u.uploads.cancel(&a);
    u.uploads.cancel(&a); // idempotent
    assert_eq!(u.temp_files(), 0);
    assert!(matches!(
        u.uploads.write_chunk(&a, 10, &[1; 10]),
        Err(CoreError::NotFound { .. })
    ));

    // Inactivity timeout.
    let short = Uploads::new(&u.env.originals()).with_timeout(Duration::from_millis(50));
    let b = short
        .begin(BeginUpload {
            project_id: p.clone(),
            file_name: "b.mp3".into(),
            size_bytes: 100,
            ..BeginUpload::default()
        })
        .unwrap()
        .upload_id;
    short.write_chunk(&b, 0, &[0; 10]).unwrap();
    assert_eq!(short.sweep_expired(), 0);
    std::thread::sleep(Duration::from_millis(120));
    assert_eq!(short.sweep_expired(), 1);
    assert_eq!(short.active_count(), 0);
    assert_eq!(u.temp_files(), 0);

    // Startup sweep: leftovers of a previous run.
    std::fs::create_dir_all(u.uploads.dir()).unwrap();
    std::fs::write(u.uploads.dir().join("vecchio.part"), b"resto").unwrap();
    let c = u.begin(&p, "c.mp3", 100, None);
    u.uploads.sweep_all();
    assert_eq!(u.temp_files(), 1, "active upload kept, leftover removed");
    u.uploads.cancel(&c);
    // The blob sweep of 0.2 never touches the uploads directory, nor vice versa.
    u.env.store.sweep_temp_files();
}

// ------------------------------------------------------------------ transcription (fake engine)

/// Fake engine: fixed segments; optional failure; optional wait for the abort flag.
#[derive(Default)]
struct FakeEngine {
    segments: Mutex<Vec<RecognizedSegment>>,
    fail: Mutex<Option<TranscribeError>>,
    block_until_abort: AtomicBool,
    calls: AtomicUsize,
    last_samples: AtomicUsize,
}

impl FakeEngine {
    fn with(segments: &[(u64, u64, &str)]) -> Arc<Self> {
        let e = FakeEngine::default();
        *e.segments.lock().unwrap() = segments
            .iter()
            .map(|&(s, t, x)| RecognizedSegment {
                start_ms: s,
                end_ms: t,
                text: x.to_owned(),
            })
            .collect();
        Arc::new(e)
    }
}

impl Transcriber for FakeEngine {
    fn transcribe(&self, r: &TranscribeRequest<'_>) -> Result<Recognized, TranscribeError> {
        self.calls.fetch_add(1, Ordering::SeqCst);
        self.last_samples.store(r.samples.len(), Ordering::SeqCst);
        assert!(r.threads >= 1);
        r.progress.store(50, Ordering::SeqCst);
        if self.block_until_abort.load(Ordering::SeqCst) {
            let start = Instant::now();
            while !r.abort.load(Ordering::SeqCst) {
                assert!(start.elapsed() < Duration::from_secs(20), "never aborted");
                std::thread::sleep(Duration::from_millis(5));
            }
            return Err(TranscribeError::Cancelled);
        }
        if let Some(err) = self.fail.lock().unwrap().clone() {
            return Err(err);
        }
        Ok(Recognized {
            language: if r.language == Language::Auto {
                "it".into()
            } else {
                r.language.as_str().into()
            },
            segments: self.segments.lock().unwrap().clone(),
        })
    }
}

/// A models directory where `tiny` counts as installed (a file of the catalog size; the
/// fake engine never reads it).
fn models_with_tiny(dir: &Path) -> ModelManager {
    let models = ModelManager::new(dir.join("models/whisper"));
    std::fs::create_dir_all(models.dir()).unwrap();
    let f = std::fs::File::create(models.dir().join("ggml-tiny.bin")).unwrap();
    f.set_len(77_691_713).unwrap();
    models
}

const SEGMENTS: &[(u64, u64, &str)] = &[
    (1_000, 3_200, " Buongiorno a tutti."),
    (
        3_200,
        6_100,
        "Oggi parliamo della derivata di una funzione.",
    ),
    (6_100, 6_150, "[BLANK_AUDIO]"),
    (
        6_150,
        9_300,
        "La derivata misura la velocità di variazione.",
    ),
];

struct Lecture {
    env: Env,
    project: String,
    doc: LibraryDocument,
    models: ModelManager,
}

impl Lecture {
    fn new(name: &str) -> Self {
        let mut env = Env::new();
        let project = env.project("Analisi").id;
        let doc = env.import(&project, name, &fixture_bytes(name));
        let models = models_with_tiny(env.dir.path());
        Lecture {
            env,
            project,
            doc,
            models,
        }
    }

    fn version(&self) -> String {
        self.doc.current.id.clone()
    }

    fn run(&mut self, engine: &dyn Transcriber) -> bool {
        self.env
            .store
            .run_next_transcription(engine, &self.models, POLL)
            .unwrap()
    }

    fn job(&self) -> localis_core::Job {
        self.env.store.list_jobs(&self.project).unwrap()[0].clone()
    }
}

#[test]
fn transcription_feeds_text_passages_and_search() {
    let mut l = Lecture::new("lezione.mp3");
    let v = l.version();
    // The fake drops nothing itself: "[BLANK_AUDIO]" is kept as given by the engine, but
    // the real engine filters it (see whisper tests); here it is a plain segment.
    let engine = FakeEngine::with(&[SEGMENTS[0], SEGMENTS[1], SEGMENTS[3]]);
    let job = l
        .env
        .store
        .start_transcription(&v, WhisperModelId::Tiny, Language::It)
        .unwrap();
    assert_eq!(job.kind, "transcribe");
    assert_eq!((job.state, job.progress), (JobState::Queued, None));
    assert_eq!(
        l.env.store.get_version(&v).unwrap().text_status,
        TextStatus::Pending
    );
    // Not twice.
    assert!(matches!(
        l.env
            .store
            .start_transcription(&v, WhisperModelId::Tiny, Language::It),
        Err(CoreError::Conflict { .. })
    ));
    // The extraction queue never takes it.
    assert!(l.env.store.claim_next_job().unwrap().is_none());

    assert!(l.run(engine.as_ref()));
    assert!(!l.run(engine.as_ref()), "queue empty");
    // 16 kHz samples of the whole recording reached the engine.
    let n = engine.last_samples.load(Ordering::SeqCst);
    assert!((144_000..160_000).contains(&n), "{n}");

    let job = l.job();
    assert_eq!((job.state, job.progress), (JobState::Done, Some(100)));
    let version = l.env.store.get_version(&v).unwrap();
    assert_eq!(version.text_status, TextStatus::Extracted);
    let info = version.transcription.unwrap();
    assert_eq!(
        (info.model.as_str(), info.language.as_str()),
        ("tiny", "it")
    );
    assert_eq!(info.segment_count, 3);

    let segments = l.env.store.get_transcript(&v).unwrap();
    assert_eq!(segments.len(), 3);
    assert_eq!(segments[0].index, 1);
    assert_eq!(segments[0].text, "Buongiorno a tutti.", "trimmed");
    assert_eq!((segments[1].start_ms, segments[1].end_ms), (3_200, 6_100));

    // get_text of a media = its segments with times.
    let units = l.env.store.get_text(&v).unwrap();
    assert_eq!(units.len(), 3);
    assert_eq!(units[2].unit, 3);
    assert_eq!(
        (units[2].start_ms, units[2].end_ms),
        (Some(6_150), Some(9_300))
    );

    // Search finds segments, with unit kind and start.
    let hits = l.env.store.search(&l.project, "velocita", None).unwrap();
    assert_eq!(hits.len(), 1);
    assert_eq!(hits[0].unit_kind, UnitKind::Segment);
    assert_eq!((hits[0].unit, hits[0].start_ms), (3, Some(6_150)));
    // Passages for chat: one, unit = first segment.
    assert_eq!(
        l.env
            .count("SELECT COUNT(*) FROM chunks WHERE unit = 1 AND ordinal = 1"),
        1
    );
    let passages = l
        .env
        .store
        .search_passages_lexical(&l.project, &[], "\"derivata\"*")
        .unwrap();
    assert_eq!(passages.len(), 1);
    assert_eq!(passages[0].unit_kind, UnitKind::Segment);
    assert_eq!(passages[0].start_ms, Some(1_000));
    // The documents list carries the transcription.
    let listed = &l.env.store.list_documents(&l.project).unwrap()[0];
    assert_eq!(
        listed.current.transcription.as_ref().unwrap().segment_count,
        3
    );
}

#[test]
fn a_new_transcript_replaces_the_old_one_only_on_success() {
    let mut l = Lecture::new("lezione.m4a");
    let v = l.version();
    let first = FakeEngine::with(SEGMENTS);
    l.env
        .store
        .start_transcription(&v, WhisperModelId::Tiny, Language::Auto)
        .unwrap();
    l.run(first.as_ref());
    assert_eq!(l.env.store.get_transcript(&v).unwrap().len(), 4);
    let info = l.env.store.get_version(&v).unwrap().transcription.unwrap();
    assert_eq!(info.language, "it", "detected language stored for auto");

    // A failing run keeps the previous transcript and its status.
    let failing = FakeEngine::with(&[]);
    *failing.fail.lock().unwrap() = Some(TranscribeError::Failed("boom".into()));
    l.env
        .store
        .start_transcription(&v, WhisperModelId::Tiny, Language::It)
        .unwrap();
    l.run(failing.as_ref());
    let job = l.job();
    assert_eq!(job.state, JobState::Failed);
    assert_eq!(
        job.error.as_deref(),
        Some("La trascrizione non è riuscita.")
    );
    assert_eq!(job.error_detail.as_deref(), Some("boom"));
    assert_eq!(l.env.store.get_transcript(&v).unwrap().len(), 4);
    assert_eq!(
        l.env.store.get_version(&v).unwrap().text_status,
        TextStatus::Extracted
    );

    // Retry with another engine result: replaced, including text, passages and FTS.
    l.env.store.retry_job(job.id).unwrap();
    let second = FakeEngine::with(&[(0, 2_000, "Un solo segmento sugli integrali.")]);
    l.run(second.as_ref());
    let segments = l.env.store.get_transcript(&v).unwrap();
    assert_eq!(segments.len(), 1);
    assert_eq!(l.env.store.get_text(&v).unwrap().len(), 1);
    assert!(l
        .env
        .store
        .search(&l.project, "derivata", None)
        .unwrap()
        .is_empty());
    assert_eq!(
        l.env
            .store
            .search(&l.project, "integrali", None)
            .unwrap()
            .len(),
        1
    );

    // No speech: no_text, transcript empty.
    l.env
        .store
        .start_transcription(&v, WhisperModelId::Tiny, Language::It)
        .unwrap();
    l.run(FakeEngine::with(&[]).as_ref());
    let version = l.env.store.get_version(&v).unwrap();
    assert_eq!(version.text_status, TextStatus::NoText);
    assert_eq!(version.transcription.unwrap().segment_count, 0);
    assert!(l.env.store.get_text(&v).unwrap().is_empty());
    assert_eq!(
        l.env.count(&format!(
            "SELECT COUNT(*) FROM chunks WHERE version_id = '{v}'"
        )),
        0
    );
}

#[test]
fn transcription_rules_and_honest_failures() {
    let mut l = Lecture::new("lezione.mp3");
    let v = l.version();
    // Not for other kinds; unknown model/language strings are input errors.
    let txt = l.env.import(&l.project, "note.txt", b"testo");
    assert!(matches!(
        l.env
            .store
            .start_transcription(&txt.current.id, WhisperModelId::Tiny, Language::It),
        Err(CoreError::Validation { .. })
    ));
    assert!(matches!(
        WhisperModelId::parse_input("enorme"),
        Err(CoreError::Validation { field: "model", .. })
    ));
    assert!(matches!(
        localis_core::parse_language("pt"),
        Err(CoreError::Validation {
            field: "language",
            ..
        })
    ));
    assert!(matches!(
        l.env
            .store
            .start_transcription("missing", WhisperModelId::Tiny, Language::It),
        Err(CoreError::NotFound { .. })
    ));

    // Model not installed at run time.
    l.env
        .store
        .start_transcription(&v, WhisperModelId::Small, Language::It)
        .unwrap();
    let engine = FakeEngine::with(SEGMENTS);
    l.run(engine.as_ref());
    let job = l.job();
    assert_eq!(job.state, JobState::Failed);
    assert_eq!(job.error.as_deref(), Some(MODEL_NOT_INSTALLED));
    assert_eq!(engine.calls.load(Ordering::SeqCst), 0);
    assert_eq!(
        l.env.store.get_version(&v).unwrap().text_status,
        TextStatus::Failed,
        "no previous transcript"
    );

    // Engine cannot load the model.
    l.env
        .store
        .start_transcription(&v, WhisperModelId::Tiny, Language::It)
        .unwrap();
    let broken = FakeEngine::with(&[]);
    *broken.fail.lock().unwrap() = Some(TranscribeError::Model("bad magic".into()));
    l.run(broken.as_ref());
    assert!(l.job().error.unwrap().contains("non può essere caricato"));

    // Missing original.
    std::fs::remove_file(l.env.blob_path(&l.doc.current.sha256)).unwrap();
    l.env
        .store
        .start_transcription(&v, WhisperModelId::Tiny, Language::It)
        .unwrap();
    l.run(engine.as_ref());
    assert!(l.job().error.unwrap().contains("archivio"));
    assert!(matches!(
        l.env.store.media_blob(&v),
        Err(CoreError::Integrity { .. })
    ));

    // A video without audio: imported, but not transcribable.
    let muto = l
        .env
        .import(&l.project, "muto.mp4", &fixture_bytes("muto.mp4"));
    l.env
        .store
        .start_transcription(&muto.current.id, WhisperModelId::Tiny, Language::It)
        .unwrap();
    l.run(engine.as_ref());
    let job = l.job();
    assert_eq!(job.state, JobState::Failed);
    assert!(job
        .error
        .unwrap()
        .contains("trascrizione non disponibile per questa codifica"));
}

#[test]
fn running_transcription_is_cancelled_through_the_abort_flag() {
    let mut l = Lecture::new("lezione.mp3");
    let v = l.version();
    // A previous transcript, kept after the cancellation.
    l.env
        .store
        .start_transcription(&v, WhisperModelId::Tiny, Language::It)
        .unwrap();
    l.run(FakeEngine::with(SEGMENTS).as_ref());

    let engine = FakeEngine::with(SEGMENTS);
    engine.block_until_abort.store(true, Ordering::SeqCst);
    let job = l
        .env
        .store
        .start_transcription(&v, WhisperModelId::Tiny, Language::It)
        .unwrap();
    // The worker runs on its own connection; the "UI" cancels on another.
    let path = l.env.db_path();
    let models = Arc::new(models_with_tiny(l.env.dir.path()));
    let engine_dyn: Arc<dyn Transcriber> = engine.clone();
    let (wake, signals) = mpsc::sync_channel(1);
    let done = Arc::new(AtomicUsize::new(0));
    let done_in = Arc::clone(&done);
    let worker = std::thread::spawn(move || {
        run_transcriber(
            || Store::open(&path),
            signals,
            TranscriberConfig {
                idle_poll: Duration::from_secs(30),
                progress_poll: POLL,
            },
            engine_dyn,
            models,
            move || {
                done_in.fetch_add(1, Ordering::SeqCst);
            },
        )
    });
    wake.send(()).unwrap();
    let mut ui = l.env.reopen();
    let start = Instant::now();
    loop {
        let j = ui.get_job(job.id).unwrap();
        if j.state == JobState::Running && j.progress.is_some_and(|p| p > 10) {
            break;
        }
        assert!(
            start.elapsed() < Duration::from_secs(20),
            "never ran: {j:?}"
        );
        std::thread::sleep(POLL);
    }
    let cancelled = ui.cancel_job(job.id).unwrap();
    assert_eq!(cancelled.state, JobState::Failed);
    assert_eq!(cancelled.error.as_deref(), Some(TRANSCRIPTION_CANCELLED));
    // The engine sees the abort flag and returns; the worker loop goes on.
    let start = Instant::now();
    while done.load(Ordering::SeqCst) < 1 {
        assert!(
            start.elapsed() < Duration::from_secs(20),
            "worker did not stop"
        );
        std::thread::sleep(POLL);
    }
    let j = ui.get_job(job.id).unwrap();
    assert_eq!(j.error.as_deref(), Some(TRANSCRIPTION_CANCELLED));
    assert_eq!(
        ui.get_transcript(&v).unwrap().len(),
        4,
        "old transcript kept"
    );
    assert_eq!(
        ui.get_version(&v).unwrap().text_status,
        TextStatus::Extracted
    );
    // Cancelling again is a conflict.
    assert!(matches!(
        ui.cancel_job(job.id),
        Err(CoreError::Conflict { .. })
    ));
    drop(wake);
    worker.join().unwrap();

    // Queued jobs (also extraction ones) can be cancelled before they run.
    let txt = l.env.import(&l.project, "note.txt", b"testo da estrarre");
    let extraction = l.env.store.list_jobs(&l.project).unwrap()[0].clone();
    assert_eq!(extraction.version_id, txt.current.id);
    let c = l.env.store.cancel_job(extraction.id).unwrap();
    assert_eq!(c.state, JobState::Failed);
    assert!(l.env.store.claim_next_job().unwrap().is_none());
    let queued = l
        .env
        .store
        .start_transcription(&v, WhisperModelId::Tiny, Language::It)
        .unwrap();
    l.env.store.cancel_job(queued.id).unwrap();
    assert!(!l.run(engine.as_ref()));
}

#[test]
fn interrupted_transcriptions_fail_at_startup_and_extraction_is_not_blocked() {
    let mut l = Lecture::new("lezione.mp3");
    let v = l.version();
    l.env
        .store
        .start_transcription(&v, WhisperModelId::Tiny, Language::It)
        .unwrap();
    let claimed = l.env.store.claim_next_transcription().unwrap().unwrap();
    assert_eq!(claimed.version_id, v);
    // Meanwhile a document is imported: its extraction is claimed by the other queue.
    let txt = l.env.import(&l.project, "note.txt", b"testo da estrarre");
    let ext = l.env.store.claim_next_job().unwrap().unwrap();
    assert_eq!(ext.version_id, txt.current.id);
    // Crash: both left running. The extraction is requeued, the transcription fails.
    let mut restarted = l.env.reopen();
    assert_eq!(restarted.requeue_interrupted_jobs().unwrap(), 1);
    assert_eq!(restarted.fail_interrupted_transcriptions().unwrap(), 1);
    let job = restarted.get_job(claimed.id).unwrap();
    assert_eq!(job.state, JobState::Failed);
    assert_eq!(job.error.as_deref(), Some(TRANSCRIPTION_INTERRUPTED));
    assert_eq!(
        restarted.get_version(&v).unwrap().text_status,
        TextStatus::Failed
    );
    // Retry runs it again.
    restarted.retry_job(claimed.id).unwrap();
    assert!(restarted
        .run_next_transcription(FakeEngine::with(SEGMENTS).as_ref(), &l.models, POLL)
        .unwrap());
    assert_eq!(restarted.get_job(claimed.id).unwrap().attempts, 2);
    // A late result for a job no longer running is discarded.
    restarted
        .finish_transcription(
            &claimed,
            &TranscriptionOutcome::Failed {
                message: "tardi".into(),
                detail: String::new(),
            },
        )
        .unwrap();
    assert_eq!(restarted.get_job(claimed.id).unwrap().state, JobState::Done);
}

#[test]
fn deleting_documents_and_projects_removes_transcripts_and_links() {
    let mut l = Lecture::new("lezione.mp4");
    let v = l.version();
    l.env
        .store
        .start_transcription(&v, WhisperModelId::Tiny, Language::It)
        .unwrap();
    l.run(FakeEngine::with(SEGMENTS).as_ref());
    let slide = l
        .env
        .import(&l.project, "slide.pdf", &pdf(&[&text_page(&[b"Derivata"])]));
    l.env.run_jobs();
    let link = l
        .env
        .store
        .create_media_link(&MediaLinkInput {
            media_version_id: v.clone(),
            start_ms: 1000,
            end_ms: 2000,
            target_version_id: slide.current.id.clone(),
            target_page: Some(1),
            ..MediaLinkInput::default()
        })
        .unwrap();
    let count = |l: &Lecture, table: &str| l.env.count(&format!("SELECT COUNT(*) FROM {table}"));
    assert_eq!(count(&l, "transcript_segments"), 4);
    l.env.store.delete_document(&l.doc.id).unwrap();
    for table in ["transcript_segments", "transcriptions", "media_links"] {
        assert_eq!(count(&l, table), 0, "{table}");
    }
    assert!(matches!(
        l.env.store.get_media_link(&link.id),
        Err(CoreError::NotFound { .. })
    ));
    // Only the PDF's text remains; the video's blob is gone.
    assert!(!l.env.blob_path(&l.doc.current.sha256).exists());
    // Project deletion: everything, but never the Whisper models.
    let again = l
        .env
        .import(&l.project, "lezione.mp4", &fixture_bytes("lezione.mp4"));
    l.env
        .store
        .start_transcription(&again.current.id, WhisperModelId::Tiny, Language::It)
        .unwrap();
    l.run(FakeEngine::with(SEGMENTS).as_ref());
    l.env.store.delete_project(&l.project).unwrap();
    for table in [
        "transcript_segments",
        "transcriptions",
        "media_links",
        "chunks",
    ] {
        assert_eq!(count(&l, table), 0, "{table}");
    }
    assert!(l.models.installed_path(WhisperModelId::Tiny).is_some());
}

