#[test]
fn media_links_validation_cascade_and_backlinks() {
    let mut l = Lecture::new("lezione.mp3");
    let v = l.version();
    let duration = l.doc.current.duration_ms.unwrap() as i64;
    let slides = l.env.import(
        &l.project,
        "slide.pdf",
        &pdf(&[&text_page(&[b"Uno"]), &text_page(&[b"Due"])]),
    );
    l.env.run_jobs();
    let photo = l.env.import(&l.project, "appunti.png", &png(8, 6));
    let notes = l.env.import(&l.project, "note.txt", b"testo");
    let input = |target: &str, page: Option<i64>| MediaLinkInput {
        media_version_id: v.clone(),
        start_ms: 1_000,
        end_ms: 4_000,
        target_version_id: target.to_owned(),
        target_page: page,
        region: None,
        note: Some("  Teorema  ".into()),
    };
    let link = l
        .env
        .store
        .create_media_link(&MediaLinkInput {
            region: Some(Region {
                x: 0.1,
                y: 0.2,
                w: 0.5,
                h: 0.3,
            }),
            ..input(&slides.current.id, Some(2))
        })
        .unwrap();
    assert_eq!(link.project_id, l.project);
    assert_eq!(link.media_document_id, l.doc.id);
    assert_eq!(link.target_document_id, slides.id);
    assert_eq!(
        (link.start_ms, link.end_ms, link.target_page),
        (1_000, 4_000, Some(2))
    );
    assert_eq!(link.note.as_deref(), Some("Teorema"));
    assert_eq!(
        (link.media_title.as_str(), link.target_title.as_str()),
        ("lezione.mp3", "slide.pdf")
    );
    assert!(link.available);
    assert_eq!(link.region.unwrap().w, 0.5);

    let image_link = l
        .env
        .store
        .create_media_link(&MediaLinkInput {
            start_ms: 0,
            end_ms: duration,
            note: None,
            ..input(&photo.current.id, None)
        })
        .unwrap();
    assert_eq!(image_link.target_page, None);

    let field = |r: Result<localis_core::MediaLink, CoreError>| match r {
        Err(CoreError::Validation { field, .. }) => field,
        other => panic!("{other:?}"),
    };
    let s = &mut l.env.store;
    assert_eq!(
        field(s.create_media_link(&input(&slides.current.id, None))),
        "targetPage"
    );
    assert_eq!(
        field(s.create_media_link(&input(&slides.current.id, Some(3)))),
        "targetPage"
    );
    assert_eq!(
        field(s.create_media_link(&input(&slides.current.id, Some(0)))),
        "targetPage"
    );
    assert_eq!(
        field(s.create_media_link(&input(&photo.current.id, Some(1)))),
        "targetPage"
    );
    assert_eq!(
        field(s.create_media_link(&input(&notes.current.id, None))),
        "targetVersionId"
    );
    assert_eq!(
        field(s.create_media_link(&MediaLinkInput {
            start_ms: -1,
            ..input(&photo.current.id, None)
        })),
        "startMs"
    );
    assert_eq!(
        field(s.create_media_link(&MediaLinkInput {
            start_ms: 4_000,
            end_ms: 4_000,
            ..input(&photo.current.id, None)
        })),
        "endMs"
    );
    assert_eq!(
        field(s.create_media_link(&MediaLinkInput {
            end_ms: duration + 1,
            ..input(&photo.current.id, None)
        })),
        "endMs"
    );
    assert_eq!(
        field(s.create_media_link(&MediaLinkInput {
            start_ms: duration,
            end_ms: duration + 10,
            ..input(&photo.current.id, None)
        })),
        "startMs"
    );
    assert_eq!(
        field(s.create_media_link(&MediaLinkInput {
            region: Some(Region {
                x: 0.8,
                y: 0.0,
                w: 0.3,
                h: 0.1
            }),
            ..input(&photo.current.id, None)
        })),
        "region"
    );
    assert_eq!(
        field(s.create_media_link(&MediaLinkInput {
            note: Some("x".repeat(2001)),
            ..input(&photo.current.id, None)
        })),
        "note"
    );
    // The media must be a recording.
    assert_eq!(
        field(s.create_media_link(&MediaLinkInput {
            media_version_id: slides.current.id.clone(),
            ..input(&photo.current.id, None)
        })),
        "mediaVersionId"
    );
    // Target in another project.
    let other = s
        .create_project(localis_core::NewProject {
            name: "Altro".into(),
            description: None,
        })
        .unwrap();
    let png_bytes = png(2, 2);
    let file = localis_core::ImportFile::prepare("altra.png", None, &png_bytes).unwrap();
    let foreign = match s.import_document(&other.id, None, &file).unwrap() {
        ImportOutcome::Imported(d) => d,
        other => panic!("{other:?}"),
    };
    assert_eq!(
        field(s.create_media_link(&input(&foreign.current.id, None))),
        "targetVersionId"
    );
    assert!(matches!(
        s.create_media_link(&input("missing", None)),
        Err(CoreError::NotFound { .. })
    ));

    // Lists, update, delete.
    assert_eq!(s.list_media_links(&v).unwrap().len(), 2);
    assert_eq!(
        s.list_media_links(&v).unwrap()[0].id,
        image_link.id,
        "by start"
    );
    let back = s.list_links_for_target(&slides.current.id).unwrap();
    assert_eq!(back.len(), 1);
    assert_eq!(back[0].id, link.id);
    let updated = s
        .update_media_link(
            &link.id,
            &MediaLinkInput {
                start_ms: 2_000,
                end_ms: 3_000,
                region: None,
                note: None,
                ..input(&slides.current.id, Some(1))
            },
        )
        .unwrap();
    assert_eq!(
        (updated.start_ms, updated.target_page, updated.region),
        (2_000, Some(1), None)
    );
    assert_eq!(updated.created_at, link.created_at);
    assert!(matches!(
        s.update_media_link("missing", &input(&photo.current.id, None)),
        Err(CoreError::NotFound { .. })
    ));
    s.delete_media_link(&image_link.id).unwrap();
    assert!(matches!(
        s.delete_media_link(&image_link.id),
        Err(CoreError::NotFound { .. })
    ));

    // Deleting the target deletes its links; originals never change.
    let before = std::fs::read(l.env.blob_path(&slides.current.sha256)).unwrap();
    assert_eq!(before, pdf(&[&text_page(&[b"Uno"]), &text_page(&[b"Due"])]));
    let s = &mut l.env.store;
    s.delete_document(&slides.id).unwrap();
    assert!(s.list_media_links(&v).unwrap().is_empty());
}

