fn fake_model(id: WhisperModelId, file: &str, body: &[u8]) -> ModelSpec {
    ModelSpec {
        id,
        name: format!("Fake {file}"),
        file_name: file.to_owned(),
        size_bytes: body.len() as u64,
        sha256: sha256_hex(body),
    }
}

const HF_PATH: &str = "/ggerganov/whisper.cpp/resolve/main/";

#[test]
fn model_download_verifies_size_and_hash() {
    let dir = tempfile::tempdir().unwrap();
    let hf = FakeHf::start();
    let good: Vec<u8> = (0..50_000u32).map(|i| (i % 251) as u8).collect();
    let catalog = vec![
        fake_model(WhisperModelId::Tiny, "ggml-tiny.bin", &good),
        fake_model(WhisperModelId::Base, "ggml-base.bin", &good),
        fake_model(WhisperModelId::Small, "ggml-small.bin", &good),
    ];
    let models =
        ModelManager::with_test_server(dir.path().join("whisper"), &hf.url, catalog).unwrap();
    // Redirect within the test origin, then the file.
    hf.route(
        &format!("{HF_PATH}ggml-tiny.bin"),
        Route::Redirect(format!("{}/cdn/tiny", hf.url)),
    );
    hf.route("/cdn/tiny", Route::Body(good.clone()));
    let listed = models.list();
    assert!(!listed[0].installed && listed[0].download.is_none());
    models.download_blocking(WhisperModelId::Tiny).unwrap();
    let listed = models.list();
    assert!(listed[0].installed);
    assert_eq!(listed[0].error, None);
    assert_eq!(
        std::fs::read(models.dir().join("ggml-tiny.bin")).unwrap(),
        good
    );
    assert_eq!(
        hf.hits(),
        [format!("{HF_PATH}ggml-tiny.bin"), "/cdn/tiny".to_owned()]
    );

    // Wrong hash (same size): error, no file, no temp left.
    let mut bad = good.clone();
    bad[100] ^= 1;
    hf.route(&format!("{HF_PATH}ggml-base.bin"), Route::Body(bad));
    let err = models.download_blocking(WhisperModelId::Base).unwrap_err();
    assert!(err.to_string().contains("SHA-256"), "{err}");
    let base = &models.list()[1];
    assert!(!base.installed);
    assert!(base.error.as_deref().unwrap().contains("SHA-256"));
    let files: Vec<_> = std::fs::read_dir(models.dir())
        .unwrap()
        .map(|e| e.unwrap().file_name().into_string().unwrap())
        .collect();
    assert_eq!(files, ["ggml-tiny.bin"]);

    // Redirect to a host outside the allowlist.
    hf.route(
        &format!("{HF_PATH}ggml-small.bin"),
        Route::Redirect("https://evil.example.com/ggml-small.bin".into()),
    );
    let err = models.download_blocking(WhisperModelId::Small).unwrap_err();
    assert!(err.to_string().contains("non consentito"), "{err}");
    assert!(!hf.hits().iter().any(|h| h.contains("evil")));

    // HTTP error.
    hf.route(&format!("{HF_PATH}ggml-small.bin"), Route::Status(404));
    let err = models.download_blocking(WhisperModelId::Small).unwrap_err();
    assert!(err.to_string().contains("HTTP 404"), "{err}");

    // Delete.
    models.delete(WhisperModelId::Tiny).unwrap();
    assert!(!models.list()[0].installed);
    models.delete(WhisperModelId::Tiny).unwrap();
}

#[test]
fn model_download_runs_in_background_and_can_be_cancelled() {
    let dir = tempfile::tempdir().unwrap();
    let hf = FakeHf::start();
    let body: Vec<u8> = vec![7u8; 64 * 400]; // ~12 s at the fake's pace
    let models = Arc::new(
        ModelManager::with_test_server(
            dir.path().join("whisper"),
            &hf.url,
            vec![fake_model(WhisperModelId::Tiny, "ggml-tiny.bin", &body)],
        )
        .unwrap(),
    );
    hf.route(&format!("{HF_PATH}ggml-tiny.bin"), Route::SlowBody(body));
    models.start_download(WhisperModelId::Tiny).unwrap();
    // A second start while downloading is a no-op.
    models.start_download(WhisperModelId::Tiny).unwrap();
    let start = Instant::now();
    loop {
        let m = &models.list()[0];
        if m.download
            .is_some_and(|(received, total)| received > 0 && total == 25_600)
        {
            break;
        }
        assert!(start.elapsed() < Duration::from_secs(10), "{m:?}");
        std::thread::sleep(POLL);
    }
    models.cancel_download(WhisperModelId::Tiny);
    let start = Instant::now();
    while models.list()[0].download.is_some() {
        assert!(start.elapsed() < Duration::from_secs(10));
        std::thread::sleep(POLL);
    }
    let m = &models.list()[0];
    assert!(!m.installed);
    assert_eq!(m.error, None, "a cancellation is not an error");
    assert_eq!(
        std::fs::read_dir(models.dir()).unwrap().count(),
        0,
        "temp removed"
    );
    assert_eq!(hf.hits().len(), 1, "only the fake server was contacted");
}

// ------------------------------------------------------------------ real whisper.cpp

/// Path of the verified `ggml-tiny.bin`, or `None` (with an explicit message) when the
/// variable is not set or the file is missing.
fn whisper_test_model(test: &str) -> Option<PathBuf> {
    match std::env::var_os("LOCALIS_WHISPER_TEST_MODEL").map(PathBuf::from) {
        Some(path) if path.is_file() => Some(path),
        Some(path) => {
            eprintln!(
                "SKIPPED {test}: LOCALIS_WHISPER_TEST_MODEL={} does not exist",
                path.display()
            );
            None
        }
        None => {
            eprintln!(
                "SKIPPED {test}: set LOCALIS_WHISPER_TEST_MODEL to a ggml-tiny.bin to run the \
                 real whisper.cpp transcription"
            );
            None
        }
    }
}

/// Models dir with the real tiny model copied in (so `installed_path` checks its size).
fn real_models(dir: &Path, model: &Path) -> ModelManager {
    let models = ModelManager::new(dir.join("models/whisper"));
    std::fs::create_dir_all(models.dir()).unwrap();
    std::fs::copy(model, models.dir().join("ggml-tiny.bin")).unwrap();
    assert!(
        models.installed_path(WhisperModelId::Tiny).is_some(),
        "the test model must be the catalog ggml-tiny.bin (77691713 bytes)"
    );
    models
}

#[test]
fn real_whisper_transcribes_italian_speech() {
    let Some(model) = whisper_test_model("real_whisper_transcribes_italian_speech") else {
        return;
    };
    for (name, language) in [
        ("lezione.mp3", Language::It),
        ("lezione.mp4", Language::Auto),
    ] {
        let mut env = Env::new();
        let p = env.project("Analisi").id;
        let doc = env.import(&p, name, &fixture_bytes(name));
        let models = real_models(env.dir.path(), &model);
        env.store
            .start_transcription(&doc.current.id, WhisperModelId::Tiny, language)
            .unwrap();
        let started = Instant::now();
        assert!(env
            .store
            .run_next_transcription(&WhisperTranscriber, &models, POLL)
            .unwrap());
        let job = &env.store.list_jobs(&p).unwrap()[0];
        assert_eq!(job.state, JobState::Done, "{name}: {job:?}");
        let segments = env.store.get_transcript(&doc.current.id).unwrap();
        let text = segments
            .iter()
            .map(|s| s.text.to_lowercase())
            .collect::<Vec<_>>()
            .join(" ");
        eprintln!(
            "{name}: {} segments in {:.1} s: {text}",
            segments.len(),
            started.elapsed().as_secs_f32()
        );
        // Synthetic TTS + the tiny model: require a few expected words, not exact text.
        let expected = [
            "buongiorno",
            "oggi",
            "derivata",
            "funzione",
            "misura",
            "variazione",
        ];
        let found = expected.iter().filter(|w| text.contains(*w)).count();
        assert!(
            found >= 2,
            "{name}: only {found} expected words in {text:?}"
        );
        assert!(!segments.is_empty());
        assert!(segments.windows(2).all(|w| w[0].start_ms <= w[1].start_ms));
        assert!(segments
            .iter()
            .all(|s| s.end_ms <= 10_500 && s.start_ms <= s.end_ms));
        let version = env.store.get_version(&doc.current.id).unwrap();
        assert_eq!(version.text_status, TextStatus::Extracted);
        assert_eq!(version.transcription.unwrap().language, "it", "{name}");
        // Recognised words are searchable, located by segment.
        let word = expected.iter().find(|w| text.contains(*w)).unwrap();
        let hits = env.store.search(&p, word, None).unwrap();
        assert!(!hits.is_empty(), "{name}: {word}");
        assert_eq!(hits[0].unit_kind, UnitKind::Segment);
        assert!(hits[0].start_ms.is_some());
    }
}

#[test]
fn real_whisper_reports_progress_and_aborts() {
    let Some(model) = whisper_test_model("real_whisper_reports_progress_and_aborts") else {
        return;
    };
    let never = AtomicBool::new(false);
    let file = std::fs::File::open(fixture("lezione.mp3")).unwrap();
    let audio = decode_to_whisper(Box::new(file), "mp3", &never, |_| {}).unwrap();
    // Progress reaches 100 on a normal run.
    let progress = std::sync::atomic::AtomicI32::new(0);
    let request = TranscribeRequest {
        model_path: &model,
        samples: &audio.samples,
        language: Language::It,
        threads: localis_core::default_threads(),
        progress: &progress,
        abort: &never,
    };
    let out = WhisperTranscriber.transcribe(&request).unwrap();
    assert_eq!(progress.load(Ordering::SeqCst), 100);
    assert!(out
        .segments
        .iter()
        .all(|s| !localis_core::is_non_speech(&s.text)));
    // An abort flag already set stops whisper.
    let abort = AtomicBool::new(true);
    let request = TranscribeRequest {
        abort: &abort,
        ..request
    };
    assert_eq!(
        WhisperTranscriber.transcribe(&request).unwrap_err(),
        TranscribeError::Cancelled
    );
    // A file that is not a model.
    let dir = tempfile::tempdir().unwrap();
    let junk = dir.path().join("ggml-junk.bin");
    std::fs::write(&junk, b"not a model").unwrap();
    let request = TranscribeRequest {
        model_path: &junk,
        abort: &never,
        ..request
    };
    assert!(matches!(
        WhisperTranscriber.transcribe(&request),
        Err(TranscribeError::Model(_))
    ));
}
